function ErrorBlock({ message }: { message?: string }) { return message ? <p className="mt-3 flex gap-2 text-xs leading-6 text-[#a04a35]"><AlertCircle className="h-4 w-4 shrink-0" />{message}</p> : null; }

// غلق البصمة في السياسة الجديدة (14:59) — يُستخدم لعرض تنبيه عدم تسجيل الانصراف.
const FINGERPRINT_CLOSE_MINUTES = 899;
function riyadhWeekday(date: Date): number {
  const weekday = new Intl.DateTimeFormat("en-US", { timeZone: "Asia/Riyadh", weekday: "short" }).format(date);
  const map: Record<string, number> = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[weekday] ?? -1;
}
function riyadhMinutes(date: Date): number {
  const parts = new Intl.DateTimeFormat("en-US", { timeZone: "Asia/Riyadh", hour: "2-digit", minute: "2-digit", hour12: false }).formatToParts(date);
  const f = (name: string) => Number(parts.find(p => p.type === name)?.value || "0");
  return f("hour") * 60 + f("minute");
}

